import { relative } from "node:path";
//#region src/internal/runners/manual.ts
/**
* Base runner that just tells developers to load the extension into their
* browser manually.
*
* You can extend this class and call any `super` method when your runner can't
* open the browser.
*/
var ManualRunner = class {
	constructor(config) {
		this.config = config;
	}
	canOpen() {
		return Promise.resolve(false);
	}
	async openBrowser() {
		this.config.logger.info(`Load "${relative(process.cwd(), this.config.outDir)}" as an unpacked extension manually`);
	}
};
//#endregion
export { ManualRunner };
